cd /Users/adriaan/repos/tt-challenges
echo "--- orgs ---"
docker compose exec -T db psql -U brain -d secondbrain -c "SELECT slug, name, kind, fund_id FROM orgs ORDER BY kind, slug;"
echo "--- RLS fails closed with no context set (expect 0 rows, not an error) ---"
docker compose exec -T db psql -U brain -d secondbrain -c "INSERT INTO documents (org_id, doc_type, file_extension, status) SELECT id, 'test', 'md', 'ready' FROM orgs WHERE slug='pc1-vantage'; SELECT count(*) AS visible_without_context FROM documents;"
echo "--- RLS scoped to pc1 only sees pc1 doc ---"
docker compose exec -T db psql -U brain -d secondbrain -c "
BEGIN;
SELECT set_config('app.current_org_ids', (SELECT id::text FROM orgs WHERE slug='pc1-vantage'), true);
SELECT count(*) AS visible_to_pc1 FROM documents;
ROLLBACK;
"
echo "--- RLS scoped to pc2 sees zero rows for pc1's doc (cross-tenant isolation) ---"
docker compose exec -T db psql -U brain -d secondbrain -c "
BEGIN;
SELECT set_config('app.current_org_ids', (SELECT id::text FROM orgs WHERE slug='pc2-cascade'), true);
SELECT count(*) AS visible_to_pc2 FROM documents;
ROLLBACK;
"

