}

.app {
  display: flex;
  flex-direction: column;
  height: 100%;
  max-width: 880px;
  margin: 0 auto;
  padding-inline: 20px;
}

.app-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
  padding-block: 22px 14px;
  border-bottom: 1px solid var(--border);
  flex-wrap: wrap;
}

.app-header h1 {
  font-family: Georgia, "Iowan Old Style", serif;
  font-size: 22px;
  margin: 0;
  font-weight: 700;
}

.app-header .eyebrow {
  display: block;
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--accent);
  font-weight: 600;
  margin-bottom: 4px;
}

.org-switcher {
  font-family: inherit;
  font-size: 13.5px;
  padding: 7px 10px;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--card);
  color: var(--ink);
}

.scope-note {
  font-size: 12px;
  color: var(--ink-muted);
  margin: 10px 0 0;
}

.thread {
  flex: 1;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 18px;
  padding-block: 20px;
}

.empty-state {
  color: var(--ink-muted);
  font-size: 13.5px;
  line-height: 1.6;
  padding-top: 40px;
  max-width: 460px;
}

.msg-user {
  align-self: flex-end;
  max-width: 75%;
  background: var(--accent-soft);
  color: var(--ink);
  padding: 10px 14px;
  border-radius: 12px 12px 2px 12px;
  font-size: 14px;
  line-height: 1.5;
}

.msg-assistant {
  align-self: stretch;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 16px 18px;
}

.msg-assistant.ungrounded {
  background: var(--amber-soft);
  border-color: var(--amber);
}

.msg-assistant .answer {
  font-size: 14.5px;
  line-height: 1.65;
  white-space: pre-wrap;
}

.msg-assistant.ungrounded .answer {
  color: var(--ink);
}

