  display: inline-block;
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--amber);
  background: #fff;
  border: 1px solid var(--amber);
  border-radius: 5px;
  padding: 2px 7px;
  margin-bottom: 10px;
}

.citations {
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.citations-label {
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--accent);
}

.citation {
  font-size: 12.5px;
  line-height: 1.5;
  color: var(--ink-muted);
  background: var(--accent-soft);
  border-radius: 7px;
  padding: 8px 10px;
}

.citation .cite-index {
  font-weight: 700;
  color: var(--accent);
  margin-right: 6px;
}

.citation .cite-source {
  font-family: "SF Mono", ui-monospace, Menlo, Consolas, monospace;
  font-size: 11.5px;
  color: var(--ink);
}

.composer {
  display: flex;
  gap: 10px;
  padding-block: 16px 22px;
  border-top: 1px solid var(--border);
}

.composer input {
  flex: 1;
  font-family: inherit;
  font-size: 14px;
  padding: 11px 14px;
  border-radius: 9px;
  border: 1px solid var(--border);
  background: var(--card);
  color: var(--ink);
}

.composer input:focus {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}

.composer button {
  font-family: inherit;
  font-size: 14px;
  font-weight: 600;
  padding: 11px 20px;
  border-radius: 9px;
  border: none;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
}

.composer button:disabled {
  opacity: 0.5;
  cursor: default;
}

.error-banner {
  font-size: 13px;
  color: var(--amber);
  background: var(--amber-soft);
  border: 1px solid var(--amber);
  border-radius: 8px;
  padding: 10px 12px;
}

