  background: var(--accent-soft);
  border-radius: 7px;
  padding: 8px 10px;
}

.citation .cite-index {
  font-weight: 700;
  color: var(--accent);
  margin-right: 6px;
}

.citation .cite-source {
  font-family: "SF Mono", ui-monospace, Menlo, Consolas, monospace;
  font-size: 11.5px;
  color: var(--ink);
}

.claim-text {
  margin: 0 0 6px;
  font-size: 12.5px;
  color: var(--ink);
  line-height: 1.5;
}

.claim-sources {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.cite-tag {
  font-family: "SF Mono", ui-monospace, Menlo, Consolas, monospace;
  font-size: 10.5px;
  color: var(--accent);
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 5px;
  padding: 2px 6px;
}

.generate-panel {
  display: flex;
  align-items: center;
  gap: 10px;
  padding-block: 14px;
  border-bottom: 1px solid var(--border);
  flex-wrap: wrap;
}

.generate-panel button {
  font-family: inherit;
  font-size: 13px;
  font-weight: 600;
  padding: 8px 14px;
  border-radius: 8px;
  border: 1px solid var(--accent);
  background: var(--accent-soft);
  color: var(--accent);
  cursor: pointer;
}

.generate-panel button:disabled {
  opacity: 0.5;
  cursor: default;
}

.brief-card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 24px 28px;
  margin-block: 18px;
}

.brief-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 14px;
}

.brief-header h2 {
  font-family: Georgia, "Iowan Old Style", serif;
  font-size: 20px;
  margin: 2px 0 0;
}

.brief-close {
  background: none;
  border: none;
  font-size: 22px;
  line-height: 1;
  color: var(--ink-muted);
  cursor: pointer;
  padding: 2px 6px;
}

.trust-surface {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 18px;
}

.trust-chip {
  font-size: 11.5px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 999px;
  background: var(--accent-soft);
  color: var(--accent);
}

.trust-chip.flag {
  background: var(--amber-soft);
  color: var(--amber);
}

.trust-chip.muted {
  background: transparent;
  border: 1px dashed var(--border);
  color: var(--ink-muted);
  font-weight: 500;
  font-style: italic;
}

.brief-body {
  font-size: 14px;
  line-height: 1.7;
}

.brief-body h3 {
  font-family: Georgia, "Iowan Old Style", serif;
  font-size: 15.5px;
  margin: 20px 0 8px;
  color: var(--accent);
}

.brief-body h3:first-child {
  margin-top: 0;
}

.brief-body p {
  margin: 0 0 10px;
}

.brief-body ul {
  margin: 0 0 10px;
  padding-left: 20px;
}

.brief-body .cite-marker {
  color: var(--accent);
  font-weight: 700;
}

.composer {
  display: flex;
  gap: 10px;
  padding-block: 16px 22px;
  border-top: 1px solid var(--border);
}

.composer input {
  flex: 1;
  font-family: inherit;
  font-size: 14px;
  padding: 11px 14px;
  border-radius: 9px;
  border: 1px solid var(--border);
  background: var(--card);
  color: var(--ink);
}

.composer input:focus {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}

.composer button {
  font-family: inherit;
  font-size: 14px;
  font-weight: 600;
  padding: 11px 20px;
  border-radius: 9px;
  border: none;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
}

.composer button:disabled {
  opacity: 0.5;
  cursor: default;
}

.dashboard {
  padding-block: 20px 40px;
  display: flex;
  flex-direction: column;
  gap: 28px;
}

.tiles {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 12px;
}

.tile {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 16px 18px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.tile-value {
  font-family: Georgia, serif;
  font-size: 28px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.tile-label {
  font-size: 12px;
  color: var(--ink-muted);
}

.tile-active .tile-value {
  color: var(--accent);
}

.tile-warn {
  border-color: var(--amber);
}

.tile-warn .tile-value {
  color: var(--amber);
}

.dash-section h2 {
  font-family: Georgia, serif;
  font-size: 15px;
  margin: 0 0 10px;
}

.dash-empty {
  font-size: 13px;
  color: var(--ink-muted);
  font-style: italic;
}

.dash-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.dash-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 10px 14px;
  font-size: 13px;
}

.dash-row.failed {
  border-color: var(--amber);
  background: var(--amber-soft);
}

.dash-row-title {
  font-weight: 600;
  font-family: "SF Mono", ui-monospace, Menlo, Consolas, monospace;
  font-size: 12.5px;
}

.dash-row-reason {
  color: var(--amber);
  font-size: 12px;
  text-align: right;
}

.dash-row-meta {
  color: var(--ink-muted);
  font-size: 12px;
  white-space: nowrap;
}

.dash-footnote {
  font-size: 11.5px;
  color: var(--ink-muted);
  font-style: italic;
  border-top: 1px solid var(--border);
  padding-top: 12px;
}

.error-banner {
  font-size: 13px;
  color: var(--amber);
  background: var(--amber-soft);
  border: 1px solid var(--amber);
  border-radius: 8px;
  padding: 10px 12px;
}

