  created_at: string;
  updated_at: string;
  org_slug: string;
}

export async function fetchDocuments(orgScope: OrgScope): Promise<DocumentRow[]> {
  const res = await fetch(`${API_BASE}/documents?orgScope=${orgScope}`);
  if (!res.ok) throw new Error("Failed to load documents");
  return res.json();
}

