cd /private/tmp/claude-501/-Users-adriaan-repos-tt-challenges/0e23f581-725d-4d6d-8f3b-11de3c978477/scratchpad
cat > verify-fixes.mjs <<'EOF'
import { chromium } from "playwright";
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 900, height: 700 } });
await page.goto("http://localhost:5173");
await page.waitForSelector(".org-switcher");
await page.selectOption(".org-switcher", "pc1-vantage");

// 1. Generate a tall brief, then confirm chat thread is still reachable by scrolling
await page.waitForFunction(() => {
  const sel = document.querySelectorAll("select.org-switcher")[1];
  return sel && sel.options.length > 1;
});
await page.selectOption("select.org-switcher >> nth=1", { label: "Priya Balakrishnan — CFO" });
await page.click(".generate-panel button");
await page.waitForSelector(".brief-card", { timeout: 30000 });
await page.waitForTimeout(300);

// ask a chat question too, while brief is showing
await page.fill(".composer input", "What is Anika Sørensen's flight risk?");
await page.click(".composer button");
await page.waitForSelector(".msg-assistant .answer", { timeout: 30000 });
await page.waitForTimeout(500);

// scroll the scroll-area all the way down and confirm the chat message is visible
await page.evaluate(() => {
  const el = document.querySelector(".scroll-area");
  el.scrollTop = el.scrollHeight;
});
await page.waitForTimeout(300);
const msgVisible = await page.evaluate(() => {
  const msg = document.querySelector(".msg-assistant .answer");
  if (!msg) return false;
  const rect = msg.getBoundingClientRect();
  return rect.top >= 0 && rect.bottom <= window.innerHeight;
});
console.log("chat message visible after scrolling past tall brief:", msgVisible);
await page.screenshot({ path: "/tmp/fix1-scroll.png" });

// 2. Check markdown bold rendering in chat answer (no literal ** in text)
const answerHtml = await page.$eval(".msg-assistant .answer", (el) => el.innerHTML);
const hasBoldTag = answerHtml.includes("<strong>");
const hasLiteralStars = (await page.$eval(".msg-assistant .answer", (el) => el.textContent)).includes("**");
console.log("answer has <strong> tags:", hasBoldTag, "| still has literal **:", hasLiteralStars);

// 3. Click a citation link and confirm the document viewer opens with real content
await page.click(".citations .cite-link >> nth=0");
await page.waitForSelector(".modal-card", { timeout: 15000 });
await page.waitForTimeout(500);
await page.screenshot({ path: "/tmp/fix3-viewer.png" });
const modalText = await page.$eval(".modal-body", (el) => el.textContent);
console.log("modal body length:", modalText.length);
const anchorHitExists = await page.$(".anchor-hit");
console.log("anchor highlighted:", !!anchorHitExists);

await browser.close();
console.log("done");
EOF
node verify-fixes.mjs

